// ilans.net/cv - generated by ~/cv-drafts/cv-build/build.py, edit there.
(function () {
  // ---------- theme toggle, same storage key as the rest of ilans.net
  var root = document.documentElement;
  var meta = document.getElementById('themeColorMeta');
  var btn = document.getElementById('themeToggle');
  function apply(light) {
    if (light) root.setAttribute('data-theme', 'light'); else root.removeAttribute('data-theme');
    if (meta) meta.setAttribute('content', light ? '#faf9f7' : '#0b0b0d');
    if (btn) btn.setAttribute('aria-pressed', light ? 'true' : 'false');
  }
  apply(root.getAttribute('data-theme') === 'light');
  if (btn) btn.addEventListener('click', function () {
    var light = root.getAttribute('data-theme') !== 'light';
    apply(light);
    try { localStorage.setItem('theme', light ? 'light' : 'dark'); } catch (e) {}
  });

  // ---------- live status: every app is pinged from the visitor's browser.
  // no-cors gives an opaque response - it proves the host answered, not the status code.
  var cards = Array.prototype.slice.call(document.querySelectorAll('.app[data-url]'));
  var sum = document.getElementById('liveSum');
  var done = 0, live = 0;

  function report() {
    if (!sum) return;
    sum.textContent = done < cards.length
      ? 'checking ' + (cards.length - done) + ' of ' + cards.length + '...'
      : live + ' of ' + cards.length + ' responding now';
  }

  function ping(card) {
    var ctl = 'AbortController' in window ? new AbortController() : null;
    var timer = setTimeout(function () { if (ctl) ctl.abort(); }, 8000);
    return fetch(card.getAttribute('data-url'), {
      mode: 'no-cors', cache: 'no-store', signal: ctl ? ctl.signal : undefined
    }).then(function () {
      card.setAttribute('data-status', 'live'); live++;
      card.querySelector('.state').textContent = 'live';
    }, function () {
      card.setAttribute('data-status', 'unreachable');
      card.querySelector('.state').textContent = 'no response from this browser';
    }).then(function () { clearTimeout(timer); done++; report(); });
  }

  report();
  cards.forEach(ping);
})();
